// ❌ POOR OPTIMIZATION
function Navbar() {
  // Returns an object. Will re-render every time ANYTHING in state.user changes.
  const { username, avatar } = useSelector(state => state.user);
}

// ✅ GREAT OPTIMIZATION
function Navbar() {
  // Primitive values! Will ONLY re-render if the username or avatar specifically change.
  const username = useSelector(state => state.user.username);
  const avatar = useSelector(state => state.user.avatar);
}
